from collections import deque
def comps(grid):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                c=grid[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and not seen[x][y] and grid[x][y]==c:
                            seen[x][y]=True; q.append((x,y))
                out.append((c,cells))
    return out

def transform(grid):
    h,w=len(grid),len(grid[0])
    Cs=comps(grid)
    # legend: comp whose cells form a solid rect with >1 distinct column colors
    legend=None; shapes=[]
    for c,cells in Cs:
        rs=[a for a,b in cells]; cs=[b for a,b in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if (r1-r0+1)*(c1-c0+1)==len(cells) and c1>c0 and len({grid[a][b] for a,b in cells})>1:
            legend=(r0,r1,c0,c1)
        else:
            shapes.append((c,(r0,r1,c0,c1),cells))
    L=[grid[legend[0]][j] for j in range(legend[2],legend[3]+1)]
    smap={c:(box,cells) for c,box,cells in shapes}
    out=[row[:] for row in grid]
    for a in range(legend[0],legend[1]+1):
        for b in range(legend[2],legend[3]+1): out[a][b]=0
    # nearest present color for each legend color
    present=[i for i,c in enumerate(L) if c in smap]
    src={}
    for i,c in enumerate(L):
        if c in smap: src[i]=smap[c]
        else:
            j=min(present,key=lambda p:abs(p-i)); src[i]=smap[L[j]]
    # anchor: first present legend index's shape stays; place contiguous stack
    a0=present[0]; box=smap[L[a0]][0]; rtop=box[0]
    for i in range(a0-1,-1,-1):
        sbox,scells=src[i]; hh=sbox[1]-sbox[0]+1
        rtop-=hh
        for a,b in scells: out[rtop+a-sbox[0]][b]=L[i]
    rbot=box[1]
    for i in range(a0+1,len(L)):
        sbox,scells=src[i]; hh=sbox[1]-sbox[0]+1
        rbot+=1
        for a,b in scells: out[rbot+a-sbox[0]][b]=L[i]
        rbot+=hh-1
    return out

