from collections import defaultdict
def transform5(grid):
    bars={}; comps=[]
    for c,cells in all_components(grid):
        rs=[a for a,b in cells]; cs=[b for a,b in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if c0==c1 and len(cells)==r1-r0+1: bars.setdefault((r0,r1),{})[c0]=c
        else: comps.append((c,set(cells)))
    span=max(bars,key=lambda s:len(bars[s]))
    cols=sorted(bars[span]); L=[bars[span][j] for j in cols]
    byc=defaultdict(set)
    for c,cells in comps: byc[c]|=cells
    shapes=[]
    for c,cells in byc.items():
        rs=[a for a,b in cells]; cs=[b for a,b in cells]
        shapes.append((c,(min(rs),max(rs),min(cs),max(cs)),cells))
    shapes.sort(key=lambda s:s[1][0])  # top to bottom
    out=[row[:] for row in grid]
    for a in range(span[0],span[1]+1):
        for b in cols: out[a][b]=0
    first, last = shapes[0], shapes[-1]
    def stamp(src, rtop, col):
        r0=src[1][0]
        for a,b in src[2]: out[rtop+a-r0][b]=col
    if first[0]!=L[0]: stamp(first, first[1][0]-(first[1][1]-first[1][0]+1), L[0])
    if last[0]!=L[-1]: stamp(last, last[1][1]+1, L[-1])
    return out
